#include <stdio.h>

/* 挨着看：从第一只开始一只只比过去，答「比了几次」；一只都没对上就答负数 */
int line_find(int a[], int n, int target) {
    int tries = 0;
    for (int i = 0; i < n; i++) {
        tries++;
        if (a[i] == target) {
            return tries;
        }
    }
    return -tries;
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) {
        return 1;
    }
    int target;
    if (scanf("%d", &target) != 1) {
        return 1;
    }
    int a[64];
    for (int i = 0; i < n; i++) {
        if (scanf("%d", &a[i]) != 1) {
            return 1;
        }
    }

    int times = line_find(a, n, target);
    if (times < 0) {
        printf("挨着看：没找到\n");
    } else {
        printf("挨着看：比了 %d 次\n", times);
    }
    return 0;
}
